package com.aistock.notification.alert;
import static com.aistock.notification.alert.AlertEvaluationRecords.*;import com.aistock.common.BusinessException;import java.time.*;import java.util.*;import java.sql.*;import java.math.BigDecimal;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;
@Service public class AlertEvaluationService {
 private final AlertMarketUseOwner uses;private final AlertRuleRepository repo;private final AlertEvaluationStore store;private final AlertEvidenceClient market;private final AlertMailAccountClient accounts;private final com.aistock.notification.alertmail.AlertMailOutbox mail;private final Clock clock;private final int updateHour;
 public AlertEvaluationService(AlertRuleRepository repo,AlertEvidenceClient market,AlertMailAccountClient accounts,com.aistock.notification.alertmail.AlertMailOutbox mail,Clock clock){this(repo,market,accounts,mail,clock,20);}
 public AlertEvaluationService(AlertRuleRepository repo,AlertEvidenceClient market,AlertMailAccountClient accounts,com.aistock.notification.alertmail.AlertMailOutbox mail,Clock clock,@org.springframework.beans.factory.annotation.Value("${aistock.market.update-hour:20}")int updateHour){this(repo,market,accounts,mail,clock,updateHour,null);}
 @org.springframework.beans.factory.annotation.Autowired public AlertEvaluationService(AlertRuleRepository repo,AlertEvidenceClient market,AlertMailAccountClient accounts,com.aistock.notification.alertmail.AlertMailOutbox mail,Clock clock,@org.springframework.beans.factory.annotation.Value("${aistock.market.update-hour:20}")int updateHour,AlertMarketUseOwner uses){this.uses=uses;if(updateHour<0||updateHour>23)throw new IllegalArgumentException("Invalid update hour");this.repo=repo;this.store=new AlertEvaluationStore(repo,clock);this.market=market;this.accounts=accounts;this.mail=mail;this.clock=clock;this.updateHour=updateHour;}
 public EvaluationReceipt evaluate(EvaluateRequest request){validate(request);var initial=rule(request.ruleId());var owner=UUID.fromString((String)initial.get("user_id"));var started=store.begin(owner,request);if(!started.dispatch())return started.receipt();
  // A second same-operation caller must not perform external work while the first is running.
  // The caller obtaining the insert owns dispatch; a persisted RUNNING is only a receipt on replay.
  try(var scope=uses==null?AlertMarketUseContext.empty():uses.acquire(owner,request,()->market.reference(request.evidenceId()))){var evidence=market.read(request.evidenceId());if(AlertMarketUseContext.expectedRaw()!=null&&!AlertMarketUseContext.expectedRaw().equals(evidence.rawVersionId().toString()))throw AlertMarketUseClient.invalid();var boundary=market.boundary((String)initial.get("instrument_id"));var account=accounts.context(owner);return store.finish(owner,request,()->apply(request,owner,evidence,boundary,account));}
  catch(BusinessException error){return store.finish(owner,request,()->result(request,"FAILED",null,error.code()));}
  catch(RuntimeException error){return store.finish(owner,request,()->result(request,"FAILED",null,"ALERT_EVALUATION_UNAVAILABLE"));}
  finally{if(uses!=null)uses.notifyCompleted(request.operationId());}
 }
 public EvaluationReceipt receipt(UUID operationId){if(operationId==null)throw invalid();return store.receipt(operationId);}
 private EvaluationReceipt apply(EvaluateRequest r,UUID owner,AlertEvidenceClient.Evidence e,AlertRecords.Boundary boundary,AlertMailAccountClient.AccountContext account){
  var row=repo.jdbc().queryForMap("select * from alert_rule where rule_id=? and user_id=? for update",r.ruleId().toString(),owner.toString());long revision=((Number)row.get("revision")).longValue();if(revision!=r.revision())return result(r,"SKIPPED_RULE_CHANGED",null,null);if(!Boolean.TRUE.equals(row.get("enabled")))return result(r,"SKIPPED_INACTIVE",null,"RULE_DISABLED");
  if(!cutoff(boundary.asOf()).equals(cutoff(clock.instant())))return result(r,"FAILED",null,"ALERT_BOUNDARY_CHANGED");
  if(account==null||!owner.equals(account.userId())||account.checkedAt().isBefore(clock.instant().minusSeconds(5))||boundary.asOf().isBefore(clock.instant().minusSeconds(5)))return result(r,"FAILED",null,"ALERT_DEPENDENCY_UNAVAILABLE");if(!"ENABLED".equals(account.status()))return result(r,"SKIPPED_INACTIVE",null,"ACCOUNT_DISABLED");
  if(!e.id().equals(r.evidenceId())||!e.instrumentId().equals(row.get("instrument_id"))||!e.tradeDate().equals(boundary.expectedCompletedTradeDate())||!e.rawVersionId().equals(boundary.rawVersionId()))return result(r,"SKIPPED_STALE",null,null);
  if(!e.tradeDate().isAfter(((java.sql.Date)row.get("effective_after_date")).toLocalDate()))return result(r,"SKIPPED_NOT_EFFECTIVE",null,null);
  store.checkedTradeDate(r.operationId(),e.tradeDate());
  var old=repo.jdbc().queryForList("select trigger_id from alert_trigger where owner_id=? and instrument_id=? and rule_id=? and trade_date=?",owner.toString(),e.instrumentId(),r.ruleId().toString(),e.tradeDate());if(!old.isEmpty())return result(r,"ALREADY_TRIGGERED",UUID.fromString((String)old.get(0).get("trigger_id")),null);
  String condition=(String)row.get("condition_code");boolean price=condition.startsWith("PRICE_");if(price&&!"VERIFIED".equals(e.priceState())||!price&&!"VERIFIED".equals(e.changeState()))return result(r,"EVIDENCE_UNAVAILABLE",null,price?"PRICE_"+e.priceState():e.changeState());
  BigDecimal threshold=(BigDecimal)row.get("threshold_value");if(!AlertComparator.matches(condition,threshold,e.rawClose()==null?null:new BigDecimal(e.rawClose()),e.previousBackwardClose()==null?null:new BigDecimal(e.previousBackwardClose()),e.currentBackwardClose()==null?null:new BigDecimal(e.currentBackwardClose())))return result(r,"NOT_MET",null,null);
  var trigger=UUID.randomUUID();var now=clock.instant();var snapshot=new Snapshot(r.ruleId(),owner,e.instrumentId(),revision,condition,threshold.stripTrailingZeros().toPlainString(),e.tradeDate(),e,now);
  repo.jdbc().update("insert into alert_trigger(trigger_id,owner_id,instrument_id,rule_id,trade_date,rule_revision,snapshot_json,created_at) values(?,?,?,?,?,?,?,?)",trigger.toString(),owner.toString(),e.instrumentId(),r.ruleId().toString(),e.tradeDate(),revision,store.json(snapshot),Timestamp.from(now));repo.jdbc().update("insert into inbox_message(message_id,trigger_id,owner_id,created_at) values(?,?,?,?)",UUID.randomUUID().toString(),trigger.toString(),owner.toString(),Timestamp.from(now));mail.capture(trigger,owner,r.ruleId(),revision,account,now);return result(r,"TRIGGERED",trigger,null);
 }
 public RulePage due(String after,int limit,String instrument){if(limit<1||limit>50||after!=null&&!AlertRemoteHttp.uuid(after)||instrument!=null&&!instrument.matches("(SH|SZ)[0-9]{6}"))throw invalid();String sql="select rule_id,user_id,instrument_id,revision,effective_after_date from alert_rule where enabled=true";var args=new ArrayList<Object>();if(after!=null){sql+=" and rule_id>?";args.add(after);}if(instrument!=null){sql+=" and instrument_id=?";args.add(instrument);}sql+=" order by rule_id limit ?";args.add(limit+1);var rows=repo.jdbc().query(sql,(rs,n)->new RuleRef(UUID.fromString(rs.getString(1)),UUID.fromString(rs.getString(2)),rs.getString(3),rs.getLong(4),rs.getDate(5).toLocalDate()),args.toArray());boolean more=rows.size()>limit;var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new RulePage(items,more?items.get(items.size()-1).ruleId().toString():null);}
 private Map<String,Object> rule(UUID id){var rows=repo.jdbc().queryForList("select * from alert_rule where rule_id=?",id.toString());if(rows.isEmpty())throw AlertEvaluationStore.error("RESOURCE_NOT_FOUND",HttpStatus.NOT_FOUND);return rows.get(0);}
 private void validate(EvaluateRequest r){if(r==null||r.operationId()==null||r.ruleId()==null||r.evidenceId()==null||r.revision()<0||r.leaseUntil()==null||r.leaseUntil().isBefore(Instant.parse("1990-01-01T00:00:00Z"))||r.leaseUntil().isAfter(clock.instant().plusSeconds(120)))throw invalid();}
 private LocalDate cutoff(Instant time){var local=time.atZone(ZoneId.of("Asia/Shanghai"));return local.toLocalDate().minusDays(local.getHour()<updateHour?1:0);}
 private static EvaluationReceipt result(EvaluateRequest r,String state,UUID trigger,String reason){return new EvaluationReceipt(r.operationId(),state,trigger,reason);}
 private static BusinessException invalid(){return AlertEvaluationStore.error("VALIDATION_FAILED",HttpStatus.BAD_REQUEST);}
}
